#!/usr/bin/env node
// Generates Unity/Assets/AshenSpire/Runtime/Domain/Original/OriginalContentSchema.cs
// from the HTML game's field schema (src/model/schemas.js + src/model/formulas.js),
// so the Unity validator (OriginalContentValidation) checks the same required fields,
// types and closed sets as src/model/validate.js. The schema is embedded as a C#
// string because the Domain assembly cannot read Unity Resources.
//
//   node tools/unity-content-schema.mjs           rewrite the generated file
//   node tools/unity-content-schema.mjs --check   exit 1 if it is out of date
//
// PREDICATE_FIELDS, FORMULA_FIELDS, COMMON_EFFECT_FIELDS and TRIGGER_FIELDS are
// module-private in src/model/validate.js, so they are restated below; keep them
// equal to validate.js when that file changes.
import {readFileSync, writeFileSync, existsSync} from 'node:fs';
import {join, dirname} from 'node:path';
import {fileURLToPath, pathToFileURL} from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const target = join(root, 'Unity/Assets/AshenSpire/Runtime/Domain/Original/OriginalContentSchema.cs');
const s = await import(pathToFileURL(join(root, 'src/model/schemas.js')).href);
const f = await import(pathToFileURL(join(root, 'src/model/formulas.js')).href);

const schema = {
  source: 'src/model/schemas.js',
  // Row tables: content path -> row schema. Rows are keyed by id in error paths.
  tables: {
    attributes: s.SCHEMAS.attribute,
    creationModes: s.SCHEMAS.creationMode,
    cards: s.SCHEMAS.card,
    resources: s.SCHEMAS.resource,
    relics: s.SCHEMAS.relic,
    statuses: s.SCHEMAS.status,
    stances: s.SCHEMAS.stance,
    keywords: s.SCHEMAS.keyword,
    enemies: s.SCHEMAS.enemy,
    encounters: s.SCHEMAS.encounter,
    events: s.SCHEMAS.event,
    flasks: s.SCHEMAS.flask,
    classes: s.SCHEMAS.class,
    'equipment.basicCardProfiles': s.SCHEMAS.basicCardProfile,
  },
  // Single objects and keyed maps of objects.
  objects: {attributeRules: s.SCHEMAS.attributeRules},
  maps: {mapConfigs: s.SCHEMAS.mapConfig},
  effectSpecs: s.EFFECT_SPECS,
  commonEffectFields: ['op', 'target', 'amount', 'if', 'repeat'],
  opcodes: s.OPCODES,
  targets: s.TARGETS,
  triggerEvents: s.TRIGGER_EVENTS,
  triggerFields: ['on', 'if', 'do', 'once', 'limitPerTurn'],
  predicates: s.PREDICATES,
  predicateFields: {
    inStance: ['stance'], hasStatus: ['of', 'status', 'atLeast'], hasBlock: ['of'], hpBelowPct: ['of', 'pct'],
    firstCardThisTurn: [], firstAttackThisCombat: [], cardTypeIs: ['type'], everyNthCardThisCombat: ['n'],
    random: ['pct'], eventIsAttack: [], eventSourceIsOwner: [], eventTargetIsOwner: [], eventStatusIs: ['status'],
    all: ['preds'], any: ['preds'], not: ['pred'],
  },
  predicateOf: ['self', 'owner', 'player', 'enemy', 'target'],
  formulaOps: f.FORMULA_OPS,
  formulaOf: f.FORMULA_OF,
  formulaFields: {
    add: ['args'], mul: ['args'], percentMaxHp: ['of', 'pct', 'min', 'max'], missingHp: ['of', 'min', 'max'],
    stacks: ['status', 'of', 'per', 'min', 'max'], energySpent: ['per', 'min', 'max'], blockOf: ['of', 'min', 'max'],
    hpOf: ['of', 'min', 'max'], cardsPlayedThisTurn: ['per', 'min', 'max'],
  },
  cardTypes: s.CARD_TYPES,
  damageSchools: s.DAMAGE_SCHOOLS,
  piles: s.PILES,
  pilePositions: s.PILE_POSITIONS,
};

for (const name of Object.keys(schema.predicateFields)) if (!s.PREDICATES.includes(name)) throw new Error(`predicateFields names unknown predicate ${name}`);
for (const name of s.PREDICATES) if (!schema.predicateFields[name]) throw new Error(`predicateFields is missing ${name}; update this tool from src/model/validate.js`);
for (const name of f.FORMULA_OPS) if (!schema.formulaFields[name]) throw new Error(`formulaFields is missing ${name}; update this tool from src/model/validate.js`);

const json = JSON.stringify(schema, null, 1);
const text = `// GENERATED by tools/unity-content-schema.mjs from src/model/schemas.js. Do not edit by hand:
// change the HTML schema (or the tool), then run: node tools/unity-content-schema.mjs
// Read by OriginalContentValidation; the descriptor kinds are those of validate.js walkSchema.
namespace AshenSpire.Domain.Original
{
    public static class OriginalContentSchema
    {
        public const string Json = @"${json.replace(/"/g, '""')}";
    }
}
`.replace(/\r?\n/g, '\n');

if (process.argv.includes('--check')) {
  const current = existsSync(target) ? readFileSync(target, 'utf8') : '';
  if (current !== text) {
    console.error('unity-content-schema: OriginalContentSchema.cs is out of date; run node tools/unity-content-schema.mjs');
    process.exit(1);
  }
  console.log('unity-content-schema: OK — generated schema matches src/model/schemas.js');
} else {
  writeFileSync(target, text);
  console.log(`unity-content-schema: wrote ${target.slice(root.length + 1)} (${Object.keys(schema.tables).length} tables)`);
}
